<script setup lang="ts">
import {onHide as onPageHide} from "@dcloudio/uni-app"
import {abandonLogin as cancelPageLogin} from "../../features/auth"
onPageHide(cancelPageLogin)

import LoginSheet from "../../components/LoginSheet.vue"

import { ref } from 'vue';import { onLoad,onShow } from '@dcloudio/uni-app';import { request,chooseMaterial,navigate,downloadFile,token,type Row } from '../../api/platform'
const id=ref(''),campaign=ref<Row|null>(null),application=ref<Row|null>(null),eligibility=ref<Row|null>(null),files=ref<Row>({}),names=ref<Row>({}),error=ref(''),busy=ref(false)
async function load(){campaign.value=await request('GET','/api/v1/review-campaigns/'+id.value);if(token()){eligibility.value=await request('GET','/api/v1/me/review-campaigns/'+id.value+'/eligibility');const rows=await request<Row[]>('GET','/api/v1/me/review-applications');const row=rows.find(a=>a.campaignId===id.value);if(row){application.value=await request('GET','/api/v1/me/review-applications/'+row.id);for(const f of application.value!.files)if(f.submissionId===application.value!.latestSubmissionId)files.value[f.requirementKey]=f.fileId}}}
async function choose(key:string){if(!token()){navigate('login');return}if(busy.value)return;busy.value=true;error.value='';try{const result=await chooseMaterial();files.value[key]=result.id;names.value[key]=result.localName}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function draft(){busy.value=true;error.value='';try{application.value=await request('POST','/api/v1/me/review-campaigns/'+id.value+'/draft',{files:files.value,expectedVersion:application.value?.lockVersion||0})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function action(action:string){if(!application.value)return;busy.value=true;error.value='';try{application.value=await request('POST','/api/v1/me/review-applications/'+application.value.id+'/actions',{action,submissionId:action==='SUBMIT'?application.value.latestSubmissionId:application.value.currentSubmissionId,expectedVersion:application.value.lockVersion})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onLoad(q=>{id.value=String(q?.id||'')})
onShow(async()=>{if(!id.value)return;error.value='';try{await load()}catch(e){error.value=(e as Error).message}})
</script>
<template><view class="page"><text class="error">{{ error }}</text><template v-if="campaign"><view class="hero"><text class="title">{{ campaign.title }}</text><text class="subtitle">截止 {{ campaign.closeAt }}</text><text v-if="application" class="badge">{{ application.status }}</text></view><button role="button" v-if="!token()" @click="navigate('login')">登录后申报</button><view v-if="eligibility" class="card"><text class="card-title">资格检查</text><text>{{ eligibility.eligible?'符合当前配置的申报资格':'部分材料要求的资格条件未满足' }}</text></view><view v-for="r in campaign.requirements" :key="r.requirementKey" class="card"><text class="card-title">{{ r.label }} {{ r.required?'(必需)':'' }}</text><text class="muted">支持 {{ JSON.parse(r.fileTypeAllowlist).join('、') }} · 上限 {{ Math.round(r.maxSize/1024) }} KB</text><text v-if="files[r.requirementKey]" class="muted">已选 {{ names[r.requirementKey]||'材料 '+files[r.requirementKey] }}</text><view class="actions"><button role="button" v-if="!application||['DRAFT','CORRECTION','WITHDRAWN'].includes(application.status)" class="secondary" :disabled="busy" @click="choose(r.requirementKey)">选择材料</button><button role="button" v-if="files[r.requirementKey]" class="quiet" @click="downloadFile(files[r.requirementKey])">查看文件</button></view></view><view v-if="token()" class="actions"><template v-if="!application||['DRAFT','CORRECTION','WITHDRAWN'].includes(application.status)"><button role="button" :disabled="busy" @click="draft">保存新草稿</button><button role="button" v-if="application?.status==='DRAFT'" :disabled="busy||!eligibility?.eligible" @click="action('SUBMIT')">提交申报</button></template><button role="button" v-if="application?.status==='SUBMITTED'" class="danger" :disabled="busy" @click="action('WITHDRAW')">撤回申报</button></view><view v-for="d in application?.decisions" :key="d.id" class="card"><text class="card-title">{{ d.decision }}</text><text>{{ d.comment }}</text><text class="muted">{{ d.decidedAt }}</text></view></template><LoginSheet/></view></template>
